class Refusal(Exception): pass

class Deadline(Exception): pass

def need(value,code):
    if not value:raise Refusal(code)

def digest(raw):return hashlib.sha256(raw).hexdigest()

def canonical(value):return (json.dumps(value,sort_keys=True,separators=(',',':'),ensure_ascii=True,allow_nan=False)+'\n').encode('ascii')

def token(raw,pattern):
    value=raw.decode('ascii','strict').strip();need(re.fullmatch(pattern,value) is not None,'TOKEN_SHAPE_REFUSED');return value

def read_regular(path,maximum=1024*1024):
    path=Path(path);before=path.lstat()
    def mark(s):return (s.st_dev,s.st_ino,s.st_mode,s.st_nlink,s.st_size,s.st_mtime_ns,s.st_ctime_ns,s.st_uid,s.st_gid)
    need(stat.S_ISREG(before.st_mode) and before.st_nlink==1 and 0<=before.st_size<=maximum,'ORDINARY_BOUNDED_FILE_REQUIRED')
    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK|os.O_CLOEXEC)
    try:
        need(mark(os.fstat(fd))==mark(before) and not os.listxattr(fd),'FILE_OPEN_CHANGED')
        with os.fdopen(fd,'rb',closefd=False) as stream:raw=stream.read(maximum+1)
        need(len(raw)==before.st_size and mark(os.fstat(fd))==mark(before) and mark(path.lstat())==mark(before),'FILE_CAPTURE_CHANGED')
        return raw
    finally:os.close(fd)

def validate_boot_identity(raw):
    need(type(raw) is bytes and re.fullmatch(
        rb'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\n',raw) is not None,
        'BOOT_ID_VALUE_REFUSED')
    return raw

def read_boot_identity():
    """Read this one procfs value without treating its reported size as bytes.

    Ordinary-file custody above is unchanged. The fixed kernel file must report
    size zero, remain the same ordinary root-owned procfs object, and return the
    same canonical UUID plus LF twice through the held descriptor.
    """
    path=Path('/proc/sys/kernel/random/boot_id')
    def mark(s):return (s.st_dev,s.st_ino,s.st_mode,s.st_nlink,s.st_size,s.st_uid,s.st_gid)
    for parent in reversed(path.parents):
        info=parent.lstat()
        need(stat.S_ISDIR(info.st_mode) and not stat.S_ISLNK(info.st_mode)
             and info.st_uid==0 and not info.st_mode&0o022,'BOOT_ID_ANCESTRY_REFUSED')
    before=path.lstat()
    need(stat.S_ISREG(before.st_mode) and before.st_nlink==1 and before.st_size==0
         and before.st_uid==before.st_gid==0 and stat.S_IMODE(before.st_mode)==0o444,
         'BOOT_ID_PROCFS_SHAPE_REFUSED')
    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK|os.O_CLOEXEC)
    try:
        need(mark(os.fstat(fd))==mark(before),'BOOT_ID_OPEN_CHANGED')
        first=validate_boot_identity(os.read(fd,129))
        need(os.lseek(fd,0,os.SEEK_SET)==0,'BOOT_ID_REWIND_REFUSED')
        second=os.read(fd,129)
        need(first==second and mark(os.fstat(fd))==mark(before)
             and mark(path.lstat())==mark(before),'BOOT_ID_READBACK_CHANGED')
        return first
    finally:os.close(fd)

def parse_json(raw):
    def pairs(values):
        result={}
        for key,value in values:
            need(key not in result,'DUPLICATE_JSON_KEY');result[key]=value
        return result
    return json.loads(raw,object_pairs_hook=pairs,parse_constant=lambda _:(_ for _ in ()).throw(Refusal('NONFINITE_JSON')))

def load_module(name):
    need(name in MODULE_PINS,'MODULE_SELECTION_REFUSED')
    path=Path(__file__).with_name(name+'.py');raw=read_regular(path,1024*1024)
    need(digest(raw)==MODULE_PINS[name],'MODULE_PIN_REFUSED')
    module=types.ModuleType('g1_hosted_'+name);module.__file__=str(path)
    exec(compile(raw,str(path),'exec'),module.__dict__)
    need(read_regular(path,1024*1024)==raw,'MODULE_CHANGED_DURING_LOAD')
    return module

def identities(path):
    p=Path(path); st=p.lstat();need(stat.S_ISDIR(st.st_mode) and not p.is_symlink(),'DIRECTORY_CUSTODY_REFUSED')
    return [st.st_dev,st.st_ino,st.st_uid]

def runtime_snapshot(source,state,u):
    run=state['run_root'];need(re.fullmatch(r'\.IMPLEMENTAUDIT/runs/[a-z0-9][a-z0-9-]*-[A-Za-z0-9]{6}',run),'RUN_ROOT_SHAPE_REFUSED')
    base=source/'.IMPLEMENTAUDIT'; expected={'.r36-locks/namespace.gate'}
    prefix=run.removeprefix('.IMPLEMENTAUDIT/')+'/'
    expected.update(prefix+n for n in (*NAMES,'phases/phase-1.md','.claimed','.controller'))
    observed={};directories=set();total=0
    for parent,dirs,files in os.walk(base,followlinks=False):
        here=Path(parent);st=here.lstat();need(stat.S_ISDIR(st.st_mode) and st.st_uid==os.geteuid() and not here.is_symlink(),'RUNTIME_DIRECTORY_REFUSED')
        directories.add(here.relative_to(base).as_posix())
        for name in dirs:need(not (here/name).is_symlink(),'RUNTIME_SYMLINK_REFUSED')
        for name in files:
            p=here/name;rel=p.relative_to(base).as_posix();st=p.lstat();need(rel in expected and st.st_uid==os.geteuid(),'RUNTIME_POPULATION_REFUSED')
            canonical_member=rel.startswith(prefix) and rel[len(prefix):] in (*NAMES,'phases/phase-1.md')
            raw=u.checked_file(p,PRIVATE_CANONICAL_BYTES if canonical_member else 65536);total+=len(raw);need(total<=512*1024,'RUNTIME_AGGREGATE_BOUND')
            observed[rel]={'bytes':len(raw),'sha256':digest(raw),'device':st.st_dev,'inode':st.st_ino}
    expected_dirs={'.','.r36-locks','runs',run.removeprefix('.IMPLEMENTAUDIT/'),run.removeprefix('.IMPLEMENTAUDIT/')+'/phases'}
    need(set(observed)==expected and directories==expected_dirs,'RUNTIME_POPULATION_REFUSED')
    need(observed['.r36-locks/namespace.gate']['bytes']==1,'RUNTIME_GATE_SHAPE_REFUSED')
    return observed

def write_private(path,raw):
    need(not path.exists(),'PRIVATE_MEMBER_ALREADY_EXISTS')
    with path.open('xb') as f:f.write(raw);f.flush();os.fsync(f.fileno())
    os.chmod(path,0o600)

def save_state(path,state):
    tmp=path.with_suffix('.next');need(not tmp.exists(),'STATE_WRITE_INTERRUPTED')
    with tmp.open('xb') as f:f.write(canonical(state));f.flush();os.fsync(f.fileno())
    os.chmod(tmp,0o600);os.replace(tmp,path)

def enable_subreaper():
    lib=ctypes.CDLL(None,use_errno=True);actual=ctypes.c_int()
    need(lib.prctl(36,1,0,0,0)==0 and lib.prctl(37,ctypes.byref(actual),0,0,0)==0 and actual.value==1,'SUBREAPER_REFUSED')

def manifest():
    raw=read_regular(Path(__file__).with_name('SOURCE_MANIFEST.json'),1024*1024)
    need(digest(raw)==MANIFEST_SHA,'MANIFEST_PIN_REFUSED');value=parse_json(raw)
    need(value.get('base_commit')==SOURCE_PARENT and value.get('expected_tree')==SOURCE_TREE
         and value.get('file_count')==SOURCE_FILES and value.get('total_bytes')==SOURCE_BYTES,'MANIFEST_SUBJECT_REFUSED')
    members={}
    for row in value['members']:
        need(type(row) is dict and set(row)=={'path','mode','git_blob','bytes','sha256'},'MANIFEST_MEMBER_SHAPE')
        path=PurePosixPath(row['path'])
        need(not path.is_absolute() and '..' not in path.parts and str(path)==row['path']
             and row['path'] not in members and row['mode'] in ('100644','100755')
             and type(row['bytes']) is int and 0<=row['bytes']<=128*1024**2
             and re.fullmatch('[0-9a-f]{40}',row['git_blob']) and re.fullmatch('[0-9a-f]{64}',row['sha256']),
             'MANIFEST_MEMBER_REFUSED')
        members[row['path']]=row
    need(len(members)==SOURCE_FILES and sum(r['bytes'] for r in members.values())==SOURCE_BYTES,'MANIFEST_POPULATION_REFUSED')
    return members

def verify_source(source,members,runtime=False):
    observed=set();total=0
    allowed={str(p) for name in members for p in PurePosixPath(name).parents if str(p)!='.'}
    for parent,dirs,files in os.walk(source,followlinks=False):
        here=Path(parent);info=here.lstat()
        need(stat.S_ISDIR(info.st_mode) and info.st_uid==info.st_gid==0
             and not info.st_mode&0o022,'SOURCE_DIRECTORY_CUSTODY_REFUSED')
        for name in list(dirs):
            path=here/name;relative=path.relative_to(source).as_posix();info=path.lstat()
            need(stat.S_ISDIR(info.st_mode) and not path.is_symlink(),'SOURCE_DIRECTORY_REFUSED')
            if here==source and name=='.git':dirs.remove(name)
            elif here==source and name=='.IMPLEMENTAUDIT':
                need(runtime,'PREEXISTING_RUNTIME_REFUSED');dirs.remove(name)
            else:need(relative in allowed,'UNEXPECTED_SOURCE_DIRECTORY')
        for name in files:
            path=here/name;relative=path.relative_to(source).as_posix()
            need(relative in members,'UNEXPECTED_SOURCE_FILE');row=members[relative];info=path.lstat()
            need(info.st_uid==info.st_gid==0 and stat.S_IMODE(info.st_mode)==(0o755 if row['mode']=='100755' else 0o644),
                 'SOURCE_FILE_MODE_REFUSED')
            raw=read_regular(path,128*1024**2)
            need(len(raw)==row['bytes'] and digest(raw)==row['sha256']
                 and hashlib.sha1(b'blob '+str(len(raw)).encode()+b'\0'+raw).hexdigest()==row['git_blob'],'SOURCE_BYTES_REFUSED')
            observed.add(relative);total+=len(raw)
    need(observed==set(members) and total==SOURCE_BYTES,'SOURCE_POPULATION_REFUSED')
    return dict(file_count=len(observed),total_bytes=total,manifest_sha256=MANIFEST_SHA,all_members_match=True)

def whole_source_census(source):
    """Preserve the complete ordinary-source envelope before provider effects."""
    rows=[];total=0
    for parent,dirs,files in os.walk(source,followlinks=False):
        for name in dirs+files:
            path=Path(parent)/name;relative=path.relative_to(source);info=path.lstat()
            need(len(relative.parts)<=40 and len(rows)<4096,'SOURCE_CENSUS_TOPOLOGY_BOUND')
            need(not path.is_symlink() and (stat.S_ISDIR(info.st_mode) or stat.S_ISREG(info.st_mode)),
                 'SOURCE_CENSUS_TYPE_REFUSED')
            row=dict(path=relative.as_posix(),mode=stat.S_IMODE(info.st_mode),kind='DIRECTORY' if stat.S_ISDIR(info.st_mode) else 'FILE')
            if stat.S_ISREG(info.st_mode):
                raw=read_regular(path,128*1024**2);total+=len(raw)
                need(total<=256*1024**2,'SOURCE_CENSUS_TOTAL_BOUND');row.update(bytes=len(raw),sha256=digest(raw))
            rows.append(row)
    return dict(files=sum(r['kind']=='FILE' for r in rows),entries=len(rows),bytes=total,population_sha256=digest(canonical(rows)),
                scope='ALL_ACTUAL_ORDINARY_SOURCE_GIT_AND_HIDDEN_ENTRIES_NO_OMISSIONS')

def configure_descriptor_capacity(state,state_path,step):
    """Establish the declared 4096 soft capacity in this one adapter process.

    A distinct sudo/Python invocation inherits its own limit. The original
    product gate stays unchanged; this prospective host configuration never
    raises or lowers the observed hard limit and expires with this process.
    """
    before=resource.getrlimit(resource.RLIMIT_NOFILE)
    need(type(before) is tuple and len(before)==2
         and all(type(v) is int and v>=-1 for v in before),'DESCRIPTOR_LIMIT_SHAPE_REFUSED')
    rows=state.setdefault('descriptor_configurations',[])
    need(step in (*STEPS,'finalize') and len(rows)<len(STEPS)+1
         and all(row['step']!=step for row in rows),'DESCRIPTOR_CONFIGURATION_SEQUENCE_REFUSED')
    row=dict(step=step,resource='RLIMIT_NOFILE',target_soft=4096,before=list(before),
        attempted=False,set_returned=False,after=None,hard_unchanged=None,established=False)
    rows.append(row);save_state(state_path,state)
    try:
        need(before[1]==resource.RLIM_INFINITY or before[1]>=4096,
             'DECLARED_DESCRIPTOR_HARD_CAPACITY_UNAVAILABLE')
        if before[0]!=4096:
            row['attempted']=True;save_state(state_path,state)
            resource.setrlimit(resource.RLIMIT_NOFILE,(4096,before[1]))
            row['set_returned']=True
    finally:
        # Read the actual result even after a refused set; never infer its state
        # from an exception. A missing readback remains unknown and fails closed.
        try:
            after=resource.getrlimit(resource.RLIMIT_NOFILE)
            need(type(after) is tuple and len(after)==2
                 and all(type(v) is int and v>=-1 for v in after),'DESCRIPTOR_LIMIT_SHAPE_REFUSED')
            row['after']=list(after)
            row['hard_unchanged']=after[1]==before[1]
            row['established']=after==(4096,before[1])
        finally:
            save_state(state_path,state)
    need(row['established'] and row['hard_unchanged'],'DESCRIPTOR_CONFIGURATION_READBACK_REFUSED')

def descriptor_configuration_public(state):
    rows=state.get('descriptor_configurations',[])
    need(type(rows) is list and len(rows)<=len(STEPS)+1,'DESCRIPTOR_PUBLIC_POPULATION_REFUSED')
    result=[];seen=set()
    for row in rows:
        need(type(row) is dict and set(row)=={'step','resource','target_soft','before',
            'attempted','set_returned','after','hard_unchanged','established'}
            and row['step'] in (*STEPS,'finalize') and row['step'] not in seen
            and row['resource']=='RLIMIT_NOFILE' and type(row['target_soft']) is int
            and row['target_soft']==4096,'DESCRIPTOR_PUBLIC_ROW_REFUSED')
        seen.add(row['step'])
        for key in ('before','after'):
            value=row[key]
            need(key=='after' and value is None or type(value) is list and len(value)==2
                 and all(type(v) is int and -1<=v<=2**63-1 for v in value),
                 'DESCRIPTOR_PUBLIC_LIMIT_REFUSED')
        need(all(type(row[key]) is bool for key in ('attempted','set_returned','established'))
             and (row['hard_unchanged'] is None or type(row['hard_unchanged']) is bool),
             'DESCRIPTOR_PUBLIC_FLAG_REFUSED')
        after=row['after'];before=row['before']
        need(row['hard_unchanged'] is (None if after is None else after[1]==before[1])
             and row['established'] is (after==[4096,before[1]])
             and (not row['set_returned'] or row['attempted']),
             'DESCRIPTOR_PUBLIC_RELATION_REFUSED')
        result.append(dict(row,before=['UNLIMITED' if v==-1 else v for v in before],
            after=None if after is None else ['UNLIMITED' if v==-1 else v for v in after]))
    return dict(schema='dg16.g1-hosted-descriptor-configuration.v1',
        scope='THIS_ADAPTER_PROCESS_AND_DESCENDANTS_ONLY',target_soft=4096,
        original_product_limit_unchanged=True,hard_limit_may_change=False,
        no_system_configuration_or_ownership_change=True,rows=result)

def inventory(state,u):
    facts=dict(uid=os.getuid(),euid=os.geteuid(),gid=os.getgid(),egid=os.getegid(),
        architecture=os.uname().machine,kernel=os.uname().release,python_version=list(sys.version_info[:3]),
        image_os=os.environ.get('ImageOS',''),image_version=os.environ.get('ImageVersion',''),tools={},
        descriptor_limits=list(resource.getrlimit(resource.RLIMIT_NOFILE)))
    state['host_observations'].append(facts)
    release={}
    for line in read_regular(Path('/etc/os-release').resolve(),16384).decode().splitlines():
        if '=' in line:
            key,value=line.split('=',1)
            if key in ('ID','VERSION_ID'):release[key]=value.strip('"')
    facts['os']=release;facts['boot_identity_sha256']=digest(read_boot_identity())
    paths={}
    for name in ('python3.12','git','bash','bwrap'):
        paths[name],facts['tools'][name]=u.trusted(name)
    need(sys.platform=='linux' and facts['architecture']=='x86_64'
         and facts['uid']==facts['euid']==facts['gid']==facts['egid']==0,'HOST_IDENTITY_REFUSED')
    need(release=={'ID':'ubuntu','VERSION_ID':'24.04'} and facts['python_version']==[3,12,3]
         and facts['image_os']=='ubuntu24' and facts['image_version']=='20261101.360.1','HOST_PROFILE_CHANGED')
    need(all(paths[name] is not None for name in ('python3.12','git','bash')),'TRUSTED_TOOL_UNAVAILABLE')
    need(facts['descriptor_limits'][0]>=4096,'DECLARED_DESCRIPTOR_CAPACITY_UNAVAILABLE')
    need(Path(sys.executable).resolve()==Path(paths['python3.12'])
         and facts['tools']['python3.12']['sha256']=='e50d468e8b0adfb05733f5b87b3cff34829c4a8c1aea50c865aa8bdfe4bb150f'
         and facts['tools']['git']['sha256']=='824d5b2fffef332ec7ba053e579659bb12f26a0b4747da6f9c6dc0e71d36f235','SELECTED_TOOL_BYTES_CHANGED')
    if paths['bwrap'] is not None:
        need(facts['tools']['bwrap']['sha256']=='52231e1caf55bcbc667b269f49c63599a6f7db4767ae6a039580d0ff853db712','LAUNCHER_BYTES_CHANGED')
    return paths

def git_identity(source,command,full=False):
    rc,out,err=command('source-identity',['/usr/bin/git','-C',str(source),'show','-s','--format=%H%n%T%n%P','HEAD'])
    need(rc==0 and not err and out.decode().splitlines()==[SOURCE_COMMIT,SOURCE_TREE,SOURCE_PARENT],'SOURCE_GIT_IDENTITY_REFUSED')
    if full:
        for label,args in (('index-clean',['diff','--cached','--quiet','--exit-code']),('tracked-clean',['diff','--quiet','--exit-code'])):
            rc,out,err=command(label,['/usr/bin/git','-C',str(source),*args]);need(rc==0 and not out and not err,'SOURCE_TRACKED_STATE_CHANGED')

def prepare_source(state,source,private,command):
    need(not source.exists() and not source.is_symlink(),'FRESH_SOURCE_REQUIRED')
    def git(label,args,seconds=60):
        rc,out,err=command(label,['/usr/bin/git','-c','protocol.https.allow=always',*args],seconds=seconds)
        need(rc==0,'ORDINARY_GIT_PREPARATION_REFUSED');return out
    git('ordinary-clone',['clone','--quiet','--no-local','--no-hardlinks','--no-checkout','--',
        'https://github.com/'+REPOSITORY+'.git',str(source)],seconds=180)
    state['source_directory_identity']=identities(source);state['git_directory_identity']=identities(source/'.git')
    branch=token(git('clone-default-branch',['-C',str(source),'symbolic-ref','--short','HEAD']),r'[A-Za-z0-9][A-Za-z0-9._/-]{0,127}')
    tracking=git('clone-actual-tracking',['-C',str(source),'config','--local','--get-regexp',r'^branch\.']).decode().splitlines()
    need(len(tracking)==2 and set(tracking)=={'branch.'+branch+'.remote origin','branch.'+branch+'.merge refs/heads/'+branch},'CLONE_TRACKING_SECTION_REFUSED')
    git('remove-observed-new-tracking',['-C',str(source),'config','--local','--remove-section','branch.'+branch])
    git('fetch-selected-commit',['-C',str(source),'fetch','--quiet','--no-tags','--no-recurse-submodules','origin',SOURCE_COMMIT],seconds=120)
    git('detach-selected-commit',['-C',str(source),'checkout','--quiet','--detach',SOURCE_COMMIT],seconds=60)
    git_identity(source,command,True)
    need(git('complete-clone',['-C',str(source),'rev-parse','--is-shallow-repository'])==b'false\n','SHALLOW_SOURCE_REFUSED')
    need(not git('new-clone-clean',['-C',str(source),'status','--porcelain=v1','--untracked-files=all','--ignored']),'FRESH_SOURCE_DIRTY')
    git('complete-object-check',['-C',str(source),'fsck','--strict','--full','--no-dangling'],seconds=120)
    # --quiet suppresses listing only; --missing=error still refuses incomplete
    # reachable objects. The maintained source owner reacquires all actual bytes.
    git('missing-object-check',['-C',str(source),'rev-list','--objects','--all','--missing=error','--quiet'],seconds=60)
    need(not git('no-imported-controller-refs',['-C',str(source),'for-each-ref','--format=%(refname)','refs/implementaudit']),
         'IMPORTED_CONTROLLER_REFS_REFUSED')
    store=load_module('source_store')
    state['loose_head']=store.retain_actual_head(source,private,SOURCE_COMMIT,SOURCE_TREE,command,read_regular,write_private)
    state['source_before']=verify_source(source,manifest(),False)
    state['source_census_before']=whole_source_census(source)
    need(digest(read_regular(source/SETUP,1024*1024))==SETUP_SHA,'SETUP_OWNER_PIN_REFUSED')

def owner(state,source,command,label,args):
    rc,out,err=command(label,['/usr/bin/bash',str(source/OWNER),*args],seconds=60)
    need(rc==0,'MAINTAINED_OWNER_REFUSED');return out

def native_step(step,state,source,output,command,u):
    controller=state['controller'];private=output/'private'
    if step=='initialize':
        raw=owner(state,source,command,'fresh-claim',['--controller',controller,'r5-g1-hosted'])
        run=token(raw,r'\.IMPLEMENTAUDIT/runs/r5-g1-hosted-[A-Za-z0-9]{6}');state['run_root']=run
        rc,out,err=command('author-real-task',['/usr/bin/python3.12','-I','-S','-B',str(source/AUTHOR),
            '--repo',str(source),'--run-root',run,'--source',str(source),'--purpose',PURPOSE,'--next-action',NEXT_ACTION])
        need(rc==0,'REAL_TASK_AUTHOR_REFUSED');value=parse_json(out)
        need(type(value) is dict and set(value)==set((*NAMES,'phases/phase-1.md')),'AUTHOR_POPULATION_REFUSED')
        for name,sha in value.items():need(digest(read_regular(source/run/name,PRIVATE_CANONICAL_BYTES))==sha,'AUTHORED_READBACK_REFUSED')
        # The exact reviewed G3 author adds native fences before activation.
        g3=load_module('checkpoint_author');g3.author_checkpoint(g3_api(state,source,output,command))
        inspected=parse_json(owner(state,source,command,'inspect-initialization',['--inspect-controller-initialization',controller,'--run-root',run]))
        init=inspected['initialization_token']
        need(type(init) is str and re.fullmatch('refs/implementaudit/controller-initializations/'+controller+r'/[0-9a-f]{32}@[0-9a-f]{40}',init),'INITIALIZATION_TOKEN_REFUSED')
        activated=parse_json(owner(state,source,command,'activate-initialization',['--activate-controller',controller,'--run-root',run,'--expected-initialization',init]))
        need(activated.get('status')=='BOUND_ELIGIBLE_FOR_NORMAL_CURRENTNESS'
             and activated.get('authority_ceiling')=='ELIGIBLE_FOR_NORMAL_CURRENTNESS_ONLY','ACTIVATION_SCOPE_REFUSED')
        state['runtime']=runtime_snapshot(source,state,u);state['initialization_sha256']=digest(canonical(activated))
    elif step=='discover':
        raw=owner(state,source,command,'discover-controller',['--current-controller',controller]);parts=raw.decode().strip().split('\t')
        need(len(parts)==4 and parts[0]==controller and Path(parts[1])==source
             and Path(parts[2])==source/state['run_root'],'CONTROLLER_CONTEXT_REFUSED')
    elif step=='invalidate':
        event='github-run-'+state['context']['run_id']+'-attempt-1-g1-fresh-hosted-job'
        raw=owner(state,source,command,'invalidate-new-session',['--invalidate-continuity',controller,'--boundary','new-session','--event',event])
        state['invalidation']=token(raw,'refs/implementaudit/continuity-invalidations/'+controller+r'@[0-9a-f]{40}')
    elif step in ('read-state','read-roadmap'):
        name='STATE.md' if step=='read-state' else 'ROADMAP.md';raw=read_regular(source/state['run_root']/name,PRIVATE_CANONICAL_BYTES)
        write_private(private/(step+'.read'),raw)
        state['reads'][name]=dict(bytes=len(raw),sha256=digest(raw),step_ordinal=len(state['completed'])+1)
        if step=='read-roadmap':need(state['reads']['STATE.md']['step_ordinal']<state['reads'][name]['step_ordinal'],'SEPARATE_READ_ORDER_REFUSED')
    elif step=='resume':
        need(set(state['reads'])=={'STATE.md','ROADMAP.md'},'CANONICAL_READS_REQUIRED')
        for name,row in state['reads'].items():need(digest(read_regular(source/state['run_root']/name,PRIVATE_CANONICAL_BYTES))==row['sha256'],'READ_BYTES_CHANGED')
        raw=owner(state,source,command,'resume-new-session',['--resume-controller',controller,'--boundary','new-session','--epoch','G0001'])
        state['receipt']=token(raw,'refs/implementaudit/continuity-receipts/'+controller+r'/G0001@[0-9a-f]{40}')
    elif step=='verify':
        raw=owner(state,source,command,'verify-resume',['--verify-resume-receipt',state['receipt']])
        need(raw.decode().strip()==state['receipt'],'VERIFIED_RECEIPT_DIFFERS')
    elif step=='require':state['first_currentness_sha256']=require_current(state,source,command,private,'initial-currentness')
    else:raise Refusal('UNKNOWN_NATIVE_STEP')

def nss_preflight(state,source,output,command,prefix):
    need(prefix in ('early','prerequisite'),'NSS_RECORD_PREFIX_REFUSED')
    private=output/'private';op=load_module('nss_preflight')
    require_current(state,source,command,private,prefix+'-nss-currentness')
    engine=op.load_selected(source);objects={}
    captured={name:engine.B.capture_selector(name,objects,limit=65536) for name in ('/etc/passwd','/etc/nsswitch.conf')}
    for name,row in captured.items():
        need(row['kind']=='FILE','NSS_FILE_CAPTURE_REFUSED');write_private(private/(prefix+'-'+Path(name).name+'.raw'),objects[row['sha256']])
    observation=op.nss_token_observation(objects[captured['/etc/nsswitch.conf']['sha256']])
    write_private(private/(prefix+'-NSS_OBSERVATION.json'),canonical(observation));state['nss_observation']=observation
    nscd={name:engine.B.capture_selector(name,objects) for name in engine.B._NSCD}
    engine.D._validate_nss(dict(files=captured,nscd=nscd),objects);engine.CHECK()
    return engine

def prepare_host_prerequisites(state,source,command,paths):
    if paths['bwrap'] is None:
        observer=load_module('launcher_observer')
        source_raw=read_regular(source/SETUP,observer.SOURCE_BYTES+1)
        observer.bind_source(source_raw)  # Exact same-runtime compile only; no setup execution.
        ordinal=state.get('command_sequence',0)
        state['launcher_provision_context']=dict(ordinal=ordinal,
            source_text=source_raw.decode('utf-8'),setup_filename=str(source/SETUP))
        rc,out,err=command('provision-absent-launcher',['/usr/bin/python3.12','-I','-S','-B',str(source/SETUP),'--provision-hosted-launcher'],seconds=60)
        # Only a returned original capture is summarized. The command's own
        # refusal/custody behavior and primary exit remain unchanged.
        complete=state['commands'][-1].get('streams_complete')
        try:
            record=observer.observe(err,source_raw,str(source/SETUP),complete)
            state['launcher_provision_capture']=dict(ordinal=ordinal,returncode=rc,
                stdout=dict(bytes=len(out),sha256=digest(out)),
                stderr_base64=base64.b64encode(err).decode('ascii'),record=record)
        except Exception as exc:
            message=str(exc).encode('utf-8','replace')
            kind=type(exc).__name__
            state['launcher_provision_error']=dict(exception_type=kind if kind in
                ('ValueError','TypeError','MemoryError','RuntimeError') else 'OTHER',
                message_bytes=len(message),message_sha256=digest(message))
            if rc==0:raise
        need(rc==0,'LAUNCHER_PROVISION_REFUSED')
    state['policy_attempted']=True
    # Save intent before the single supported policy effect; no retry is allowed.
    save_state(Path(state['private_state_path']),state)
    rc,out,err=command('provision-fixed-bwrap-policy',['/usr/bin/env','GITHUB_ACTIONS=true','RUNNER_ENVIRONMENT=github-hosted',
        '/usr/bin/python3.12','-I','-S','-B',str(source/SETUP),'--provision-hosted-bwrap-policy'],seconds=60)
    need(rc==0,'BWRAP_POLICY_PROVISION_REFUSED')
    state['policy_provision_sha256']=digest(out)

def configure_actual_nss(state,source,output):
    need(state['run_root'] is None and state['receipt'] is None
         and state['nss_configuration_attempted'] is False,'NSS_CONFIGURATION_PRECONTROLLER_ONLY')
    state['nss_configuration_attempted']=True
    save_state(output/'private/episode.json',state)
    module=load_module('nss_configuration')
    try:
        module.prepare(output/'private',state['context']['run_id'],write_private)
    finally:
        path=output/'private/NSS_CONFIGURATION.json'
        if path.exists():
            state['nss_configuration']=parse_json(read_regular(path,8192))
        save_state(output/'private/episode.json',state)
    need(state['nss_configuration'].get('configured') is True,'NSS_CONFIGURATION_NOT_COMPLETED')
    module.verify_configured(state['nss_configuration'])

def check_actual_nss(state,output):
    held=state.get('nss_configuration')
    need(type(held) is dict and held.get('configured') is True,'NSS_CONFIGURATION_NOT_COMPLETED')
    observed=parse_json(read_regular(output/'private/NSS_CONFIGURATION.json',8192))
    need(observed==held,'NSS_CONFIGURATION_JOURNAL_CHANGED')
    return load_module('nss_configuration').verify_configured(observed)

def integer(value,maximum=2**63-1):
    return value if type(value) is int and 0<=value<=maximum else None

def boolean(value):return value if type(value) is bool else False

def observed_boolean(value):return value if type(value) is bool else None

def aggregate_child_observation(state):
    # A new finalizer process cannot receive a lost predecessor's descendants.
    # Preserve an explicit failed cleanup; otherwise unclosed custody is unknown.
    value=state.get('all_step_children_reaped')
    if value is False:return False
    if state.get('active_step') is not None or state.get('prior_step_children_unknown') is True:return None
    return observed_boolean(value)

def finite_number(value):
    return value if type(value) in (int,float) and math.isfinite(value) and 0<=value<=10**9 else None

def hash_value(value):
    return value if type(value) is str and re.fullmatch('[0-9a-f]{64}',value) else None

def enum_value(value,population,fallback='UNESTABLISHED'):
    return value if type(value) is str and value in population else fallback

def binding(value):
    raw=canonical(value);return dict(bytes=len(raw),sha256=digest(raw))

def short_token(value,pattern):
    return value if type(value) is str and re.fullmatch(pattern,value) else None

def validate_nss_effect(value):
    fields={'schema','authority','phase','replacement','configured','temporary_creation_recorded','temporary_removal_recorded',
        'temporary_false_meaning',
        'failure_code','before','after','changed_rows','original_gate_unchanged','ownership_changed',
        'product_source_changed','disposition'}
    module=load_module('nss_configuration')
    need(type(value) is dict and set(value)==fields
         and value['schema']=='dg16.g1-nss-effect-observation.v1' and value['authority']=='NONE'
         and value['phase'] in module.PHASES and value['replacement'] in ('NOT_STARTED','STARTED_OUTCOME_UNKNOWN','COMPLETED')
         and (value['configured'] is None or type(value['configured']) is bool)
         and type(value['temporary_creation_recorded']) is bool and type(value['temporary_removal_recorded']) is bool
         and value['temporary_false_meaning']=='NO_DURABLE_COMPLETION_OBSERVATION_NOT_PROOF_OF_ABSENCE'
         and (value['failure_code'] is None or value['failure_code'] in module.REFUSALS
             or value['failure_code']=='NSS_CONFIGURATION_UNCLASSIFIED_REFUSAL')
         and value['changed_rows']==['passwd'] and value['original_gate_unchanged'] is True
         and value['ownership_changed'] is False and value['product_source_changed'] is False
         and value['disposition']=='RETAIN_CONFIGURED_FILE_UNTIL_VM_DISPOSAL','NSS_EFFECT_PUBLIC_SCHEMA')
    for name in ('before','after'):
        row=value[name]
        need(row is None or type(row) is dict and set(row)=={'bytes','sha256','physical_sha256'}
             and integer(row['bytes'],65536) is not None and hash_value(row['sha256']) is not None
             and hash_value(row['physical_sha256']) is not None,'NSS_EFFECT_PUBLIC_OBSERVATION')
    need((value['replacement']=='COMPLETED')==(value['configured'] is True)
         and (value['replacement']!='STARTED_OUTCOME_UNKNOWN' or value['configured'] is None)
         and (value['replacement']!='NOT_STARTED' or value['configured'] is False),'NSS_EFFECT_PUBLIC_CONTRADICTION')
    return value

def require_complete_packet():
    need(set(MODULE_PINS)=={'host_utility','source_store','nss_configuration',
         'checkpoint_author','nss_preflight','source_admission','diagnostic_case','policy_observer','launcher_observer','access_matrix'},'PACKET_MODULE_POPULATION_REFUSED')
    for name,pin in MODULE_PINS.items():
        need(type(pin) is str and re.fullmatch('[0-9a-f]{64}',pin),'PACKET_UNSEALED')
        need(digest(read_regular(Path(__file__).with_name(name+'.py'),1024*1024))==pin,
             'PACKET_MODULE_PIN_REFUSED')
    for name,pin in DATA_PINS.items():
        need(digest(read_regular(Path(__file__).with_name(name),1024*1024))==pin,'PACKET_DATA_PIN_REFUSED')


def host_context(output,source):
    e=os.environ
    need(e.get('GITHUB_ACTIONS')=='true' and e.get('GITHUB_REPOSITORY')==REPOSITORY
         and e.get('GITHUB_EVENT_NAME')=='push' and e.get('GITHUB_REF')=='refs/heads/'+BRANCH
         and e.get('GITHUB_RUN_ATTEMPT')=='1' and e.get('RUNNER_ENVIRONMENT')=='github-hosted','EVENT_GUARD_REFUSED')
    run=e.get('GITHUB_RUN_ID','');workflow=e.get('GITHUB_SHA','')
    need(re.fullmatch('[0-9]{1,20}',run) and re.fullmatch('[0-9a-f]{40}',workflow),'HOSTED_IDENTITY_REFUSED')
    workspace=Path(e['GITHUB_WORKSPACE']).resolve(strict=True);temp=Path(e['RUNNER_TEMP']).resolve(strict=True)
    need(output==temp/('dg16-g1-intake-diagnostic-'+run+'-1')
         and source==workspace/'qualified-g1-intake-source'
         and Path(__file__).absolute().parent==workspace/'packet/qualification/dg16-r5-g1-intake-diagnostic',
         'RESOURCE_SCOPE_REFUSED')
    return dict(repository=REPOSITORY,branch=BRANCH,run_id=run,run_attempt=1,workflow_commit=workflow)


def fresh_state(context,output):
    now=time.monotonic()
    return dict(schema='dg16.g1-intake-diagnostic-private.v1',context=context,
        controller='r5-g1-hosted-'+context['run_id']+'-a1',run_root=None,receipt=None,
        completed=[],failed=False,failures=[],reads={},runtime=None,commands=[],command_custody=[],
        currentness=[],host_observations=[],started_monotonic=now,deadline_monotonic=now+RUN_SECONDS,
        output_directory_identity=identities(output),source_directory_identity=None,git_directory_identity=None,
        source_before=None,source_after=None,source_unchanged=False,runtime_unchanged=False,
        all_step_children_reaped=True,active_step=None,interrupted_step=None,prior_step_children_unknown=False,
        policy_attempted=False,policy_finalized=False,nss_configuration_attempted=False,
        nss_configuration=None,nss_configuration_final=None,matrix_reserved=False,matrix_started=False,matrix_received=False,
        matrix_capture=None,matrix_result=None,case_reserved=False,case_received=False,
        case_started=False,case_capture=None,case_result=None,case_test_failed=None,public_eligible=False,
        policy_window_reserved=False,policy_window_context=None,policy_window_record=None,
        policy_window_errors=[],policy_window_close_status='NOT_OPENED',
        launcher_provision_context=None,launcher_provision_capture=None,launcher_provision_error=None,
        source_admission_reserved=False,source_admission_started=False,source_admission_received=False,
        source_admission_capture=None,source_admission_result=None)


def cwd_role(source):
    current=Path.cwd()
    return ('SELECTED_SOURCE' if current==source else 'FILESYSTEM_ROOT' if current==Path('/') else 'OTHER')


def require_current(state,source,command,private,label):
    need(label in CURRENTNESS_ROLES,'CURRENTNESS_ROLE_REFUSED')
    row=dict(role=label,cwd_role=cwd_role(source),attempted=False,returncode=None,
             stdout=None,stderr=None,receipt_matches=None,complete=False,known_stderr_literals=[])
    need(not any(x['role']==label for x in state['currentness']),'CURRENTNESS_REPLAY_REFUSED')
    state['currentness'].append(row)
    need(row['cwd_role']=='SELECTED_SOURCE','CURRENTNESS_SOURCE_CWD_REQUIRED')
    row['attempted']=True;save_state(private/'episode.json',state)
    rc=None;out=err=b''
    try:
        rc,out,err=command(label,['/usr/bin/bash',str(source/OWNER),
                                '--require-current-continuity',state['controller']],seconds=30)
        row['complete']=True
    except BaseException as exc:
        captured=getattr(exc,'captured',{})
        rc=captured.get('returncode');out=captured.get('stdout',out);err=captured.get('stderr',err)
        raise
    finally:
        row.update(returncode=rc,stdout=dict(bytes=len(out),sha256=digest(out)),
                   stderr=dict(bytes=len(err),sha256=digest(err)))
        row['known_stderr_literals']=closed_stderr_literals(err)
        row['receipt_matches']=(rc==0 and out==state['receipt'].encode()+b'\n') if rc is not None else None
        save_state(private/'episode.json',state)
    # Preserve the maintained exact receipt conjunction; diagnostics grant none.
    need(rc==0 and out.decode().strip()==state['receipt'],'CURRENTNESS_REFUSED')
    need(row['receipt_matches'],'CURRENTNESS_RECEIPT_BYTES_REFUSED')
    return digest(out)


def g3_api(state,source,output,command):
    return dict(source=source,run_root=state['run_root'],controller=state['controller'],receipt=state['receipt'],
        private=output/'private',command=command,deadline_monotonic=state['deadline_monotonic'],
        require_current=lambda label:require_current(state,source,command,output/'private',label),
        read_regular=read_regular,write_private=write_private)


def closed_stderr_literals(raw):
    child=load_module('diagnostic_case');p=child.profile()
    return child.literal_codes(raw,p)


def command_custody_established(state,index):
    return (len(state['commands'])==index+1 and state['commands'][index].get('process_started') is True
            and (state['commands'][index].get('cleanup') or {}).get('echild') is True
            and state.get('all_step_children_reaped') is True
            and state.get('prior_step_children_unknown') is False)


def source_admission_projection(state):
    support=load_module('source_admission');p=support.profile()
    flags={name:state.get('source_admission_'+name,False) for name in ('reserved','started','received')}
    need(all(type(value) is bool for value in flags.values()),'SOURCE_ADMISSION_FLAGS')
    need(not flags['started'] or flags['reserved'],'SOURCE_ADMISSION_START_RELATION')
    need(not flags['received'] or flags['started'],'SOURCE_ADMISSION_RECEIVE_RELATION')
    value=state.get('source_admission_result');capture=state.get('source_admission_capture')
    if value is not None: support.validate_record(value,p)
    if capture is not None:
        need(type(capture) is dict and set(capture)=={'returncode','streams_complete','stdout','stderr','child_custody_established'},
             'SOURCE_ADMISSION_CAPTURE_FIELDS')
        need(capture['returncode'] is None or type(capture['returncode']) is int and -255<=capture['returncode']<=255,
             'SOURCE_ADMISSION_CAPTURE_RC')
        need(type(capture['streams_complete']) is bool and type(capture['child_custody_established']) is bool,
             'SOURCE_ADMISSION_CAPTURE_FLAGS')
        for key in ('stdout','stderr'):validate_stream_descriptor(capture[key],1024*1024)
    need((value is not None)==flags['received'],'SOURCE_ADMISSION_RECORD_RELATION')
    if flags['received']:
        raw=canonical(value)
        need(capture is not None and capture['streams_complete'] is True
             and capture['returncode']==(0 if value['admitted'] else 1)
             and capture['stdout']==dict(bytes=len(raw),sha256=digest(raw))
             and capture['stderr']==dict(bytes=0,sha256=digest(b'')),'SOURCE_ADMISSION_CAPTURE_BINDING')
    return dict(schema='dg16.g1-intake-source-admission-observation.v1',authority='NONE',
        module_sha256=MODULE_PINS['source_admission'],profile_sha256=DATA_PINS['DIAGNOSTIC_PROFILE.json'],
        **flags,capture=capture,record=value,record_sha256=digest(canonical(value)) if value is not None else None,
        before_host_prerequisites_and_controller=True,native_case_permission=False,original_acceptance=False)


def checked_source_admission(state):
    value=source_admission_projection(state)
    need(value['reserved'] and value['started'] and value['received']
         and value['capture']['child_custody_established'] is True
         and value['record']['admitted'] is True,'SOURCE_ADMISSION_NOT_ADMITTED')
    return value['record_sha256']


def compile_only_source_admission(state,source,output,command):
    private=output/'private'
    need(state['run_root'] is None and state['receipt'] is None and state['policy_attempted'] is False
         and state['nss_configuration_attempted'] is False,'SOURCE_ADMISSION_PRECONTROLLER_ONLY')
    need(state['source_admission_reserved'] is False and state['source_admission_started'] is False,
         'SOURCE_ADMISSION_REPLAY_REFUSED')
    support=load_module('source_admission');p=support.profile()
    child_path=Path(__file__).with_name('source_admission.py');child_raw=read_regular(child_path,1024*1024)
    need(digest(child_raw)==MODULE_PINS['source_admission'],'SOURCE_ADMISSION_EXECUTING_BYTES_PIN')
    state['source_admission_reserved']=True;save_state(private/'episode.json',state)
    out=err=b'';rc=None;complete=False;error=None
    index=len(state['commands']);state['source_admission_started']=True;save_state(private/'episode.json',state)
    try:
        rc,out,err=command('compile-only-source-admission',['/usr/bin/python3.12','-I','-S','-B','-c',
            VERIFIED_CHILD_BOOTSTRAP,str(child_path),child_raw.decode('utf-8','strict'),'--compile-only',str(source)],seconds=60)
        complete=True
    except BaseException as exc:
        captured=getattr(exc,'captured',{})
        rc=captured.get('returncode');out=captured.get('stdout',out);err=captured.get('stderr',err)
        complete=captured.get('streams_complete',False);error=exc
    finally:
        write_private(private/'source-admission.stdout',out);write_private(private/'source-admission.stderr',err)
        state['source_admission_capture']=dict(returncode=rc,streams_complete=complete,
            stdout=dict(bytes=len(out),sha256=digest(out)),stderr=dict(bytes=len(err),sha256=digest(err)),
            child_custody_established=command_custody_established(state,index))
        if complete and not err:
            try:
                value=support.validate_record(parse_json(out),p)
                need(out==canonical(value) and rc==(0 if value['admitted'] else 1),'SOURCE_ADMISSION_EXIT_BINDING')
                state['source_admission_result']=value;state['source_admission_received']=True
            except (ValueError,KeyError,TypeError,Refusal,support.Refusal):
                state['source_admission_received']=False
        save_state(private/'episode.json',state)
    if error is not None:raise error
    return checked_source_admission(state)


def policy_window_error(state,code):
    need(code in ('OBSERVER_EXCEPTION','RECORD_UNAVAILABLE','CLOSE_UNAVAILABLE'),'POLICY_WINDOW_ERROR_CODE')
    if code not in state['policy_window_errors']:state['policy_window_errors'].append(code)


def retain_policy_window(state,window):
    # All observer failures are secondary to the original captured case result.
    if window.record['status']=='ABORTED_BEFORE_DRAIN' and window.record['case_launch_attempted']:
        window.record['status']='OBSERVER_INTERRUPTED'
    try:window.close()
    except BaseException:policy_window_error(state,'CLOSE_UNAVAILABLE')
    state['policy_window_close_status']=window.record['close_status']
    try:state['policy_window_record']=window.public()
    except BaseException:
        state['policy_window_record']=None;policy_window_error(state,'RECORD_UNAVAILABLE')


def policy_window_projection(state,commands):
    observer=load_module('policy_observer')
    reserved=state.get('policy_window_reserved');context=state.get('policy_window_context')
    record=state.get('policy_window_record');errors=state.get('policy_window_errors')
    closing=state.get('policy_window_close_status')
    need(type(reserved) is bool and type(errors) is list and len(errors)<=3
        and all(type(x) is str and x in ('OBSERVER_EXCEPTION','RECORD_UNAVAILABLE','CLOSE_UNAVAILABLE') for x in errors)
        and len(errors)==len(set(errors)),'POLICY_WINDOW_ERROR_SHAPE')
    need(type(closing) is str and closing in ('NOT_OPENED','CLOSED','CLOSE_UNAVAILABLE'),'POLICY_WINDOW_CLOSE_SHAPE')
    if not reserved:
        need(context is None and record is None and not errors and closing=='NOT_OPENED'
            and state['case_started'] is False,'POLICY_WINDOW_NOT_ATTEMPTED_RELATION')
    else:
        need(type(context) is dict and set(context)=={'source_admission_sha256','policy_provision_sha256','bwrap'},
            'POLICY_WINDOW_CONTEXT_SHAPE')
        need(hash_value(context['source_admission_sha256']) is not None
            and context['source_admission_sha256']==checked_source_admission(state)
            and hash_value(context['policy_provision_sha256']) is not None
            and context['policy_provision_sha256']==state.get('policy_provision_sha256'),'POLICY_WINDOW_CONTEXT_JOIN')
        binary=context['bwrap']
        need(type(binary) is dict and set(binary)=={'bytes','sha256','canonical_path_sha256'}
            and type(binary['bytes']) is int and binary['bytes']==72160
            and type(binary['sha256']) is str and binary['sha256']==observer.BWRAP_SHA256
            and hash_value(binary['canonical_path_sha256']) is not None,'POLICY_WINDOW_BINARY_SHAPE')
        actual=state['host_observations'][-1]['tools']['bwrap']
        need(type(actual['canonical']) is str and actual['bytes']==binary['bytes'] and actual['sha256']==binary['sha256']
            and digest(actual['canonical'].encode('utf-8'))==binary['canonical_path_sha256'],'POLICY_WINDOW_BINARY_JOIN')
        need(record is not None or 'RECORD_UNAVAILABLE' in errors,'POLICY_WINDOW_RECORD_RELATION')
    selected=[row for row in commands if row['role']=='synthetic-access-matrix']
    need(len(selected)<=1,'POLICY_WINDOW_CASE_POPULATION')
    if record is not None:
        observer.validate(record)
        need(record['attempted'] and record['close_status']==closing
            and record['case_launch_attempted']==state['case_started'],'POLICY_WINDOW_ATTEMPT_JOIN')
        if selected:
            row=selected[0];capture=state['case_capture']
            need(record['case_process_started'] is row['process_started']
                and type(capture) is dict and row['returncode']==capture['returncode']
                and record['case_capture_complete'] is capture['streams_complete']
                and (not record['case_capture_complete'] or row['streams_complete'] is True)
                and record['case_child_custody_established'] is capture['child_custody_established'],
                'POLICY_WINDOW_CAPTURE_JOIN')
            if row['streams_complete']:
                need(row['stdout']==capture['stdout'] and row['stderr']==capture['stderr'],'POLICY_WINDOW_STREAM_JOIN')
        else:need(not record['case_process_started'] and not record['case_capture_complete']
                  and not record['case_child_custody_established'],'POLICY_WINDOW_NO_PROCESS_JOIN')
    result=dict(schema='dg16.g1-parent-policy-observation.v1',authority='NONE',reserved=reserved,
        context=context,record=record,errors=errors,descriptor_close_status=closing,
        read_to_eagain_without_observed_loss=observer.read_complete(record) if record is not None else False,
        collection_is_not_case_process_attribution=True,
        case_record_sha256=digest(canonical(state['case_result'])) if state['case_result'] is not None else None,
        observation_does_not_change_case_result=True,no_denial_absence_or_cause_claim=True)
    need(len(canonical(result))<=8192,'POLICY_WINDOW_PUBLIC_BOUND')
    return result


def diagnostic_matrix(state,source,output,command):
    private=output/'private';admission=checked_source_admission(state)
    require_current(state,source,command,private,'before-access-matrix')
    need(not state['matrix_reserved'] and not state['matrix_started'],'ONE_MATRIX_REPLAY_REFUSED')
    module=load_module('access_matrix');path=Path(__file__).with_name('access_matrix.py')
    raw=read_regular(path,1024*1024);need(digest(raw)==MODULE_PINS['access_matrix'],'MATRIX_BYTES_PIN')
    state['matrix_reserved']=True;save_state(private/'episode.json',state)
    index=len(state['commands']);error=None
    try:
        state['matrix_started']=True;save_state(private/'episode.json',state)
        rc,out,err=command('synthetic-access-matrix',['/usr/bin/env','GITHUB_ACTIONS=true','RUNNER_ENVIRONMENT=github-hosted',
            '/usr/bin/python3.12','-I','-S','-B','-c',VERIFIED_CHILD_BOOTSTRAP,str(path),raw.decode(),
            '--source',str(source),'--private',str(private/'access-matrix'),'--admission',admission],seconds=95)
        state['matrix_capture']=dict(returncode=rc,streams_complete=state['commands'][-1].get('streams_complete') is True,
            stdout=dict(bytes=len(out),sha256=digest(out)),stderr=dict(bytes=len(err),sha256=digest(err)),
            child_custody_established=command_custody_established(state,index))
        if rc==0 and not err and state['matrix_capture']['streams_complete'] and command_custody_established(state,index):
            matrix_raw=read_regular(private/'access-matrix/result.json',65536)
            need(parse_json(out)==dict(matrix=dict(bytes=len(matrix_raw),sha256=digest(matrix_raw))),'MATRIX_CAPTURE_JOIN')
            value=parse_json(matrix_raw);module.validate(value)
            need(value['source_admission_sha256']==admission,'MATRIX_ADMISSION_JOIN')
            state['matrix_result']=value;state['matrix_received']=True
    except BaseException as exc:error=exc
    finally:save_state(private/'episode.json',state)
    if command_custody_established(state,index):require_current(state,source,command,private,'after-access-matrix')
    else:state['after_case_currentness_skipped']='CHILD_CUSTODY_NOT_ESTABLISHED'
    if error is not None:raise error
    need(state['matrix_received'],'MATRIX_RESULT_UNAVAILABLE')
    return True


def record_failure(state,step,exc):
    raw=str(exc).encode('utf-8','replace');kind=type(exc).__name__
    state['failed']=True
    need(len(state['failures'])<32,'FAILURE_POPULATION_BOUND')
    state['failures'].append(dict(step=step if step in (*STEPS,'finalize','cleanup','export') else 'OTHER',
        exception_type=kind if kind in ('Refusal','ValueError','RuntimeError','OSError','FileNotFoundError',
            'PermissionError','KeyError','TypeError','Deadline','KeyboardInterrupt','SystemExit') else 'OTHER',
        code=str(exc) if str(exc) in KNOWN_FAILURE_CODES else 'ORCHESTRATION_TIMEOUT'
             if isinstance(exc,Deadline) else 'UNCLASSIFIED_EXCEPTION',
        message_bytes=len(raw),message_sha256=digest(raw),
        errno=exc.errno if isinstance(exc,OSError) and type(exc.errno) is int and 0<=exc.errno<=4096 else None))


def final_currentness(state,source,output,command):
    # P01 correction: selecting the executable by absolute path did not select
    # its repository. All source/custody checks precede this exact cwd binding.
    os.chdir(source)
    state['final_currentness_sha256']=require_current(state,source,command,output/'private','final-currentness')


def execute(step,source,output):
    context=host_context(output,source);require_complete_packet()
    u=load_module('host_utility');state_path=output/'private/episode.json'
    if step=='prepare':
        need(not output.exists() and not output.is_symlink(),'SINGLE_ATTEMPT_OUTPUT_EXISTS')
        output.mkdir(mode=0o755);(output/'private').mkdir(mode=0o700);(output/'public').mkdir(mode=0o755)
        state=fresh_state(context,output);state['private_state_path']=str(state_path);save_state(state_path,state)
    else:
        state=parse_json(read_regular(state_path,4*1024**2))
        need(state['schema']=='dg16.g1-intake-diagnostic-private.v1' and state['context']==context
             and identities(output)==state['output_directory_identity'],'LIVE_CONTEXT_CHANGED')
        if state['source_directory_identity'] is not None:
            need(identities(source)==state['source_directory_identity']
                 and identities(source/'.git')==state['git_directory_identity'],'SOURCE_DIRECTORY_CHANGED')
    enabled=False;success=False;owned_step=False;test_passed=True;oldcwd=Path.cwd();os.chdir('/')
    deadline=time.monotonic()+FINAL_SECONDS if step=='finalize' else state['deadline_monotonic']
    def expired(_a,_b):raise Deadline()
    signal.signal(signal.SIGALRM,expired);signal.signal(signal.SIGTERM,expired)
    signal.alarm(max(1,int(deadline-time.monotonic())))
    def command(label,argv,seconds=COMMAND_SECONDS):
        need(label in COMMAND_ROLES,'COMMAND_LABEL_REFUSED')
        ordinal=state.get('command_sequence',0);need(ordinal<48,'COMMAND_POPULATION_BOUND')
        state['command_sequence']=ordinal+1;before=len(state['commands'])
        # Only a closed cwd relation is retained; no private path is published.
        relation=dict(ordinal=ordinal,step=step,role=label,cwd_role=cwd_role(source))
        state['command_custody'].append(relation)
        base=output/'private'/('command-%04d'%ordinal);rc=None;out=err=b''
        try:
            rc,out,err=u.capture(step+'-'+label,argv,state['commands'],deadline,seconds=seconds)
            return rc,out,err
        except BaseException as exc:
            captured=getattr(exc,'captured',{})
            out=captured.get('stdout',out);err=captured.get('stderr',err)
            raise
        finally:
            if len(state['commands'])==before:
                state['commands'].append(dict(name=step+'-'+label,process_started=False,returncode=None,
                    streams_complete=False,internal_failure=dict(code='CAPTURE_DID_NOT_PRODUCE_CHILD_RECORD')))
            relation['stdout']=dict(bytes=len(out),sha256=digest(out))
            relation['stderr']=dict(bytes=len(err),sha256=digest(err))
            relation['known_stderr_literals']=closed_stderr_literals(err)
            write_private(base.with_suffix('.stdout'),out);write_private(base.with_suffix('.stderr'),err)
    try:
        enable_subreaper();enabled=True
        if step!='finalize':
            need(not state['failed'] and len(state['completed'])<len(STEPS)
                 and STEPS[len(state['completed'])]==step,'STEP_ORDER_OR_PRIOR_FAILURE')
            need(state.get('active_step') is None,'PRIOR_STEP_OUTCOME_UNKNOWN')
            state['active_step']=step;save_state(state_path,state);owned_step=True
            configure_descriptor_capacity(state,state_path,step);paths=inventory(state,u)
            if step=='prepare':
                prepare_source(state,source,output/'private',command)
                compile_only_source_admission(state,source,output,command)
                prepare_host_prerequisites(state,source,command,paths)
                configure_actual_nss(state,source,output);inventory(state,u)
                state['host_baseline']=state['host_observations'][-1]
            else:
                checked_source_admission(state)
                need(state['host_observations'][-1]==state['host_baseline'],'HOST_OR_TOOLCHAIN_CHANGED')
                check_actual_nss(state,output);git_identity(source,command,False)
                verify_source(source,manifest(),state['run_root'] is not None)
                if state['runtime'] is not None:
                    need(runtime_snapshot(source,state,u)==state['runtime'],'CANONICAL_RUNTIME_CHANGED')
                os.chdir(source)
                if step in NATIVE_STEPS:native_step(step,state,source,output,command,u)
                elif step=='input-preflight':nss_preflight(state,source,output,command,'early')
                elif step=='access-matrix':test_passed=diagnostic_matrix(state,source,output,command)
                else:raise Refusal('UNKNOWN_STEP')
                verify_source(source,manifest(),state['run_root'] is not None)
                if state['runtime'] is not None:
                    need(runtime_snapshot(source,state,u)==state['runtime'],'CANONICAL_RUNTIME_CHANGED')
            state['completed'].append(step);success=True
        else:
            configure_descriptor_capacity(state,state_path,step)
            if state.get('active_step') is not None:
                state['interrupted_step']=state['active_step'];state['prior_step_children_unknown']=True
                state['all_step_children_reaped']=None;save_state(state_path,state)
            nss_journal=output/'private/NSS_CONFIGURATION.json'
            if nss_journal.exists():state['nss_configuration']=parse_json(read_regular(nss_journal,8192))
            cleanup=u.stop_owned_children();state['final_child_cleanup']=cleanup
            need(cleanup['echild'],'FINAL_CHILD_CUSTODY_REFUSED')
            if (state.get('nss_configuration') or {}).get('configured') is True:
                state['nss_configuration_final']=check_actual_nss(state,output)
            if state['source_directory_identity'] is not None:
                if state.get('policy_attempted') is True:
                    checked_source_admission(state)
                    need(digest(read_regular(source/SETUP,1024*1024))==SETUP_SHA,'SETUP_OWNER_PIN_REFUSED')
                    rc,out,err=command('observe-bwrap-policy-finalization',['/usr/bin/env','GITHUB_ACTIONS=true','RUNNER_ENVIRONMENT=github-hosted',
                        '/usr/bin/python3.12','-I','-S','-B',str(source/SETUP),'--finalize-hosted-bwrap-policy'],seconds=30)
                    state['policy_finalization_sha256']=digest(out);state['policy_finalized']=rc==0
                    need(rc==0,'POLICY_FINALIZATION_REFUSED')
                git_identity(source,command,True);state['source_after']=verify_source(source,manifest(),state['run_root'] is not None)
                state['source_unchanged']=state['source_before']==state['source_after']
                if state['runtime'] is not None:
                    state['runtime_unchanged']=runtime_snapshot(source,state,u)==state['runtime']
                    need(state['source_unchanged'] and state['runtime_unchanged'],'FINAL_SOURCE_RUNTIME_CHANGED')
                    if state['all_step_children_reaped'] and state['receipt'] is not None:
                        final_currentness(state,source,output,command)
            checked_source_admission(state)
            need(not state['failed'] and state['completed']==list(STEPS) and state['matrix_received']
                 and state['source_unchanged'] and state['runtime_unchanged']
                 and state.get('final_currentness_sha256') is not None,'DIAGNOSTIC_INCOMPLETE')
            success=True
    except BaseException as exc:
        record_failure(state,step,exc)
    finally:
        signal.alarm(10)
        try:
            cleanup=u.stop_owned_children() if enabled else dict(echild=not u.children(),pidfd_signals=0,reaped_statuses=[])
            state['last_child_cleanup']=cleanup
            need(cleanup['echild'],'STEP_CHILD_CLEANUP_UNCERTAIN')
        except BaseException as exc:
            state['all_step_children_reaped']=False;success=False;record_failure(state,'cleanup',exc)
        if owned_step and state['all_step_children_reaped'] is True:state['active_step']=None
        state['elapsed_ns']=int((time.monotonic()-state['started_monotonic'])*10**9)
        if step=='finalize':state['terminal_collection_complete']=success
        save_state(state_path,state)
        if step=='finalize':
            try:
                state['effect_observations']=effect_observations(output)
                save_state(state_path,state);write_public(state,output)
            except BaseException as exc:
                success=False;record_failure(state,'export',exc);save_state(state_path,state)
        signal.alarm(0);os.chdir(oldcwd)
    print('DG16_G1_INTAKE_STAGE '+step+' '+('COLLECTED' if success else 'REFUSED'),flush=True)
    return 0 if success and test_passed else 1


def effect_observations(output):
    records={}
    for role,name,limit,module_name in (
        ('NSS','NSS_CONFIGURATION.json',8192,'nss_configuration'),
        ('PARENT_CHECKPOINT','G3_EFFECT_STATE.json',4096,'checkpoint_author')):
        row=dict(status='NOT_OBSERVED',bytes=None,sha256=None,public=None)
        try:
            raw=read_regular(output/'private'/name,limit)
            row.update(status='EXACT_RECORD_SCHEMA_UNQUALIFIED',bytes=len(raw),sha256=digest(raw))
            module=load_module(module_name)
            value=(module.public_state(parse_json(raw)) if role=='NSS' else module.validate_effect_state(raw))
            if role=='NSS':validate_nss_effect(value)
            else:
                need(value['completed'] in ([],['AUTHORED']) and not value['root_consumed']
                     and not value['consumption_reserved'] and value['original_awards']==0
                     and all(v=='NOT_STARTED' for v in value['effects'].values()),'AUTHOR_ONLY_EFFECT_SCOPE')
            row.update(status='EXACT_CLOSED_RECORD_OBSERVED',public=value)
        except FileNotFoundError:pass
        except Exception:
            if row['bytes'] is None:row['status']='UNREADABLE_OR_GUARD_REFUSED'
        records[role]=row
    return records


def validate_effect_observations(value):
    need(type(value) is dict and set(value)=={'NSS','PARENT_CHECKPOINT'},'EFFECT_POPULATION')
    for role,row in value.items():
        need(type(row) is dict and set(row)=={'status','bytes','sha256','public'}
             and row['status'] in ('NOT_OBSERVED','EXACT_RECORD_SCHEMA_UNQUALIFIED',
             'EXACT_CLOSED_RECORD_OBSERVED','UNREADABLE_OR_GUARD_REFUSED'),'EFFECT_FIELDS')
        if row['status'].startswith('EXACT_'):
            need(integer(row['bytes'],8192) is not None and hash_value(row['sha256']) is not None,'EFFECT_BINDING')
        else:need(row['bytes'] is None and row['sha256'] is None,'EFFECT_UNKNOWN_BINDING')
        if row['status']=='EXACT_CLOSED_RECORD_OBSERVED':
            if role=='NSS':validate_nss_effect(row['public'])
            else:
                actual=load_module('checkpoint_author').validate_effect_state(canonical(row['public']))
                need(actual['completed'] in ([],['AUTHORED']) and not actual['root_consumed']
                     and not actual['consumption_reserved'] and actual['original_awards']==0
                     and all(v=='NOT_STARTED' for v in actual['effects'].values()),'AUTHOR_ONLY_EFFECT_SCOPE')
        else:need(row['public'] is None,'EFFECT_UNKNOWN_PUBLIC')
    return value


def cleanup_projection(value):
    if value is None:return None
    need(type(value) is dict,'CLEANUP_MAPPING')
    statuses=value.get('reaped_statuses',[])
    need(type(statuses) is list and len(statuses)<=64,'CLEANUP_STATUS_POPULATION')
    codes=[]
    for row in statuses:
        rc=row.get('returncode')
        need(type(rc) is int and -255<=rc<=255,'CLEANUP_RETURN_CODE');codes.append(rc)
    return dict(echild=observed_boolean(value.get('echild')),pidfd_signals=integer(value.get('pidfd_signals'),4096),
        retained_status_count=len(statuses),returncodes=codes,
        reaped_statuses_truncated=boolean(value.get('reaped_statuses_truncated')),
        reported_status_count=integer(value.get('retained_status_count'),4096),
        record_binding=binding(value))


def command_projection(state):
    rows=state['commands'];custody=state['command_custody']
    need(type(rows) is list and len(rows)<=48 and len(rows)==len(custody),'COMMAND_LEDGER_POPULATION')
    out=[]
    allowed_reasons=set(COMMAND_REASONS)
    for index,(row,held) in enumerate(zip(rows,custody)):
        need(held['ordinal']==index and held['role'] in COMMAND_ROLES and held['step'] in (*STEPS,'finalize')
             and held['cwd_role'] in ('SELECTED_SOURCE','FILESYSTEM_ROOT','OTHER')
             and row['name']==held['step']+'-'+held['role'],'COMMAND_ROLE_BINDING')
        rc=row.get('returncode');reason=row.get('reason_code')
        need(rc is None or type(rc) is int and -255<=rc<=255,'COMMAND_RETURN_CODE')
        need(reason is None or reason in allowed_reasons,'COMMAND_REASON_REFUSED')
        for key in ('stdout','stderr'):
            validate_stream_descriptor(held[key],1024*1024)
        validate_literals(held['known_stderr_literals'])
        failure=row.get('internal_failure') or {}
        captured={}
        for key in ('stdout','stderr'):
            value=dict(bytes=row.get(key+'_bytes'),sha256=row.get(key+'_sha256'))
            if value['bytes'] is None or value['sha256'] is None:captured[key]=None
            else:
                validate_stream_descriptor(value,1024*1024);captured[key]=value
        returned_matches=(captured['stdout']==held['stdout'] and captured['stderr']==held['stderr'])
        if row.get('streams_complete') is True:
            need(returned_matches,'COMPLETE_CAPTURE_RETURN_BINDING')
        out.append(dict(ordinal=index,step=held['step'],role=held['role'],cwd_role=held['cwd_role'],
            process_started=boolean(row.get('process_started')),returncode=rc,
            streams_complete=boolean(row.get('streams_complete')),timed_out=boolean(row.get('timeout')),
            output_bound_exceeded=boolean(row.get('output_bound_exceeded')),pidfd_acquired=boolean(row.get('pidfd_acquired')),
            reason_code=reason or 'UNESTABLISHED',start_errno=integer(row.get('start_errno'),4096),
            internal_failure_code=enum_value(failure.get('code'),INTERNAL_COMMAND_FAILURES),
            internal_failure_errno=integer(failure.get('errno'),4096),stdout=captured['stdout'],stderr=captured['stderr'],
            returned_capture=(None if returned_matches else dict(stdout=held['stdout'],stderr=held['stderr'])),
            returned_capture_matches_record=returned_matches,
            known_stderr_literals=held['known_stderr_literals'],cleanup=cleanup_projection(row.get('cleanup')),
            raw_record=binding(row)))
    return out


def validate_stream_descriptor(value,maximum):
    need(type(value) is dict and set(value)=={'bytes','sha256'} and integer(value['bytes'],maximum) is not None
         and hash_value(value['sha256']) is not None,'STREAM_DESCRIPTOR_REFUSED')


def validate_literals(value):
    child=load_module('diagnostic_case');p=child.profile()
    allowed={key for key,_ in child.LITERALS}|set(p['transport_codes'])
    need(type(value) is list and len(value)==len(set(value)) and all(x in allowed for x in value),'STDERR_LITERAL_REFUSED')


def currentness_projection(state):
    rows=state['currentness'];seen=set()
    need(type(rows) is list and len(rows)<=len(CURRENTNESS_ROLES),'CURRENTNESS_POPULATION')
    for row in rows:
        need(type(row) is dict and set(row)=={'role','cwd_role','attempted','returncode','stdout','stderr',
             'receipt_matches','complete','known_stderr_literals'} and row['role'] in CURRENTNESS_ROLES
             and row['role'] not in seen,'CURRENTNESS_FIELDS');seen.add(row['role'])
        need(row['cwd_role'] in ('SELECTED_SOURCE','FILESYSTEM_ROOT','OTHER') and type(row['attempted']) is bool
             and type(row['complete']) is bool and (row['receipt_matches'] is None or type(row['receipt_matches']) is bool)
             and (row['returncode'] is None or type(row['returncode']) is int and -255<=row['returncode']<=255),
             'CURRENTNESS_TYPES')
        for key in ('stdout','stderr'):
            if row[key] is not None:validate_stream_descriptor(row[key],1024*1024)
        validate_literals(row['known_stderr_literals'])
        if row['receipt_matches']:
            need(row['attempted'] and row['complete'] and row['returncode']==0
                 and row['cwd_role']=='SELECTED_SOURCE','CURRENTNESS_MATCH_RELATION')
    return rows


def launcher_provision_projection(state,commands):
    rows=[row for row in commands if row['role']=='provision-absent-launcher']
    need(len(rows)<=1 and all(row['step']=='prepare' for row in rows),'ACTUAL_JOIN_REFUSED')
    captured=state.get('launcher_provision_capture')
    error=state.get('launcher_provision_error')
    if error is not None:
        need(type(error) is dict and set(error)=={'exception_type','message_bytes','message_sha256'}
             and error['exception_type'] in ('ValueError','TypeError','MemoryError','RuntimeError','OTHER')
             and type(error['message_bytes']) is int and 0<=error['message_bytes']<=32768
             and hash_value(error['message_sha256']) is not None and len(rows)==1,'CLOSED_SCHEMA_REFUSED')
    if captured is None:
        return dict(status='OBSERVER_REFUSED' if error is not None else 'NOT_RECORDED',
            command_ordinal=rows[0]['ordinal'] if rows else None,
            primary_returncode=rows[0]['returncode'] if rows else None,record=None,observer_error=error)
    context=state.get('launcher_provision_context')
    need(type(context) is dict and set(context)=={'ordinal','source_text','setup_filename'}
         and type(captured) is dict and set(captured)=={'ordinal','returncode','stdout','stderr_base64','record'}
         and len(rows)==1 and error is None,'CLOSED_SCHEMA_REFUSED')
    row=rows[0]
    need(type(context['ordinal']) is int and type(captured['ordinal']) is int
         and context['ordinal']==captured['ordinal']==row['ordinal']
         and type(captured['returncode']) is int and captured['returncode']==row['returncode']
         and row['process_started'] is True and row['returned_capture_matches_record'] is True
         and row['cleanup']['echild'] is True,'ACTUAL_JOIN_REFUSED')
    need(type(captured['stderr_base64']) is str and len(captured['stderr_base64'])<=43692
         and type(context['source_text']) is str and len(context['source_text'])<=78790,
         'BYTE_BOUND_REFUSED')
    raw=base64.b64decode(captured['stderr_base64'],validate=True)
    need(base64.b64encode(raw).decode('ascii')==captured['stderr_base64'] and len(raw)<=32768,
         'BYTE_BOUND_REFUSED')
    need(dict(bytes=len(raw),sha256=digest(raw))==row['stderr'] and captured['stdout']==row['stdout'],
         'COMPLETE_CAPTURE_RETURN_BINDING')
    validate_stream_descriptor(captured['stdout'],32768)
    observer=load_module('launcher_observer')
    observer.validate_against(captured['record'],raw,context['source_text'].encode('utf-8'),
        context['setup_filename'],row['streams_complete'])
    observations=state.get('host_observations',[])
    need(observations and captured['record']['runtime']['version']==observations[-1]['python_version'],
         'ACTUAL_JOIN_REFUSED')
    return dict(status='RECORDED',command_ordinal=row['ordinal'],primary_returncode=row['returncode'],
        record=captured['record'],observer_error=None)


def public_projection(state):
    context=state['context'];observations=state.get('host_observations',[])
    need(context['repository']==REPOSITORY and context['branch']==BRANCH
         and re.fullmatch('[0-9]{1,20}',context['run_id']) and re.fullmatch('[0-9a-f]{40}',context['workflow_commit'])
         and context['run_attempt']==1,'PUBLIC_CONTEXT')
    host=observations[-1] if observations else {};tools={}
    for name in ('python3.12','git','bash','bwrap'):
        row=host.get('tools',{}).get(name,{})
        tools[name]=dict(available=boolean(row.get('available')),bytes=integer(row.get('bytes')),
            sha256=hash_value(row.get('sha256')),canonical_path_sha256=digest(str(row.get('canonical','')).encode()),
            root_owned_nonwritable_chain=boolean(row.get('root_owned_nonwritable_chain')),
            setid_or_file_capabilities=boolean(row.get('setid_or_file_capabilities')))
    effects=validate_effect_observations(state.get('effect_observations') or
        {x:dict(status='NOT_OBSERVED',bytes=None,sha256=None,public=None) for x in ('NSS','PARENT_CHECKPOINT')})
    admission=source_admission_projection(state)
    matrix=state.get('matrix_result')
    if matrix is not None:
        child=load_module('access_matrix');child.validate(matrix)
        need(matrix['source_admission_sha256']==admission['record_sha256'],'MATRIX_ADMISSION_JOIN')
    rows=currentness_projection(state);commands=command_projection(state)
    completed=state['completed']
    need(type(completed) is list and completed==list(STEPS[:len(completed)]),'PUBLIC_COMPLETED_ORDER')
    terminal=state.get('terminal_collection_complete') is True
    test_pass=False
    if terminal:
        checked_source_admission(state)
        need(not state['failed'] and completed==list(STEPS) and state['matrix_reserved'] is True
             and state['matrix_started'] is True and state['matrix_received'] is True and matrix is not None
             and state['all_step_children_reaped'] is True and state['source_unchanged'] is True
             and state['runtime_unchanged'] is True and [r['role'] for r in rows]==list(CURRENTNESS_ROLES)
             and all(r['attempted'] and r['complete'] and r['receipt_matches'] for r in rows),
             'TERMINAL_COLLECTION_CONJUNCTION')
    status=('ACCESS_MATRIX_'+matrix['status']+'_NO_ACCEPTANCE') if terminal else 'ACCESS_MATRIX_PARENT_REFUSED_OR_INCOMPLETE'
    capture=state.get('matrix_capture')
    if capture is not None:
        need(type(capture) is dict and set(capture)=={'returncode','streams_complete','stdout','stderr','child_custody_established'},
             'CASE_CAPTURE_FIELDS')
        need(capture['returncode'] is None or type(capture['returncode']) is int and -255<=capture['returncode']<=255,
             'CASE_CAPTURE_RETURN_CODE')
        need(type(capture['streams_complete']) is bool and type(capture['child_custody_established']) is bool,'CASE_CAPTURE_FLAGS')
        for key in ('stdout','stderr'):validate_stream_descriptor(capture[key],1024*1024)
    failures=[]
    for row in state['failures']:
        need(type(row) is dict and set(row)=={'step','exception_type','code','message_bytes','message_sha256','errno'},'FAILURE_FIELDS')
        need(row['step'] in (*STEPS,'finalize','cleanup','export','OTHER') and row['code'] in
             (*KNOWN_FAILURE_CODES,'UNCLASSIFIED_EXCEPTION','ORCHESTRATION_TIMEOUT'),'FAILURE_CODE')
        failures.append(dict(step=row['step'],code=row['code'],
            exception_type=enum_value(row['exception_type'],('Refusal','ValueError','RuntimeError','OSError','FileNotFoundError',
                'PermissionError','KeyError','TypeError','Deadline','KeyboardInterrupt','SystemExit','OTHER')),
            message_bytes=integer(row['message_bytes']),message_sha256=hash_value(row['message_sha256']),errno=integer(row['errno'],4096)))
    need(len(failures)<=32,'FAILURE_POPULATION_BOUND')
    census=state.get('source_census_before') or {}
    docs={
      'RESULT.json':dict(schema='dg16.g1-intake-diagnostic-result.v1',authority='NONE',status=status,
        scope='SEVEN_SYNTHETIC_ACCESS_ROWS_ONLY',**context,source_commit=SOURCE_COMMIT,source_tree=SOURCE_TREE,
        completed_steps=completed,elapsed_ns=integer(state.get('elapsed_ns')),orchestration_watchdog_seconds=RUN_SECONDS,
        diagnostic_collection_complete=terminal,observed_test_pass=test_pass,
        bank_acceptance=False,original_G1_award=False,original_G3_award=False,original_acceptance=False,
        whole_DG16_awarded=False,audit_closure=False,automatic_retry=False,provider_allocated=False,
        g1_operation_invoked=False,g3_consumption_invoked=False,private_state_binding=binding(state)),
      'HOST.json':dict(schema='dg16.g1-intake-diagnostic-host.v1',
        os_id=enum_value(host.get('os',{}).get('ID'),('ubuntu',)),
        os_version=short_token(host.get('os',{}).get('VERSION_ID'),r'[0-9]{2}\.[0-9]{2}'),
        architecture=enum_value(host.get('architecture'),('x86_64',)),
        kernel=short_token(host.get('kernel'),r'[A-Za-z0-9._+-]{1,80}'),
        image_os=short_token(host.get('image_os'),r'ubuntu[0-9]{2}'),
        image_version=short_token(host.get('image_version'),r'[0-9]{8}\.[0-9]{1,8}\.[0-9]{1,4}'),
        uid=integer(host.get('uid'),2**32-1),euid=integer(host.get('euid'),2**32-1),
        gid=integer(host.get('gid'),2**32-1),egid=integer(host.get('egid'),2**32-1),
        python_version=[integer(v,10000) for v in host.get('python_version',[])[:3]],tools=tools,
        descriptor_limits=[integer(v) if v!=-1 else 'UNLIMITED' for v in host.get('descriptor_limits',[])[:2]],
        descriptor_configuration=descriptor_configuration_public(state),observed_host_records=len(observations),
        observation_binding=binding(observations),command_count=len(commands),commands=commands,
        launcher_provision=launcher_provision_projection(state,commands)),
      'SOURCE.json':dict(schema='dg16.g1-intake-diagnostic-source.v1',commit=SOURCE_COMMIT,tree=SOURCE_TREE,parent=SOURCE_PARENT,
        manifest_sha256=MANIFEST_SHA,expected_files=SOURCE_FILES,expected_bytes=SOURCE_BYTES,
        before_match=boolean((state.get('source_before') or {}).get('all_members_match')),
        after_match=boolean((state.get('source_after') or {}).get('all_members_match')),
        source_unchanged=boolean(state.get('source_unchanged')),runtime_unchanged=boolean(state.get('runtime_unchanged')),
        complete_source_census={k:integer(census.get(k)) for k in ('files','entries','bytes')},
        complete_source_census_sha256=hash_value(census.get('population_sha256')),
        loose_head_status=enum_value((state.get('loose_head') or {}).get('status'),
            ('EXISTING_ACTUAL_LOOSE_HEAD_VERIFIED','ACTUAL_GIT_GENERATED_LOOSE_HEAD_RETAINED')),
        loose_head_binding=binding(state.get('loose_head')),tracked_source_mutations=False,
        receipt_binding=binding(dict(controller=state.get('controller'),receipt=state.get('receipt'),reads=state.get('reads'))),
        exported_refs_or_receipts=False),
      'SOURCE_ADMISSION.json':admission,
      'DIAGNOSTIC.json':dict(schema='dg16.g1-intake-diagnostic-observation.v1',authority='NONE',
        selected_test=None,profile_sha256=DATA_PINS['DIAGNOSTIC_PROFILE.json'],matrix_reserved=boolean(state.get('matrix_reserved')),
        matrix_started=boolean(state.get('matrix_started')),matrix_received=boolean(state.get('matrix_received')),
        matrix_capture=capture,actual_matrix=matrix,parent_checkpoint=effects['PARENT_CHECKPOINT'],
        policy_window=None,maintained_case_invoked=False,
        historical_hosted03r1_cause='UNKNOWN_NOT_RETAINED',monkeypatch_or_trace_hooks=False,
        owner_call_replay=False,raw_tracebacks_or_private_streams_uploaded=False,bank_acceptance=False),
      'CURRENTNESS.json':dict(schema='dg16.g1-intake-diagnostic-currentness.v1',authority='NONE',observations=rows,
        after_case_skip=enum_value(state.get('after_case_currentness_skipped'),('CHILD_CUSTODY_NOT_ESTABLISHED',),'NONE_RECORDED'),
        exported_observations_convey_currentness=False,finalizer_source_cwd_required=True),
      'NSS.json':dict(schema='dg16.g1-intake-diagnostic-nss.v1',actual_effect=effects['NSS'],
        early_preflight_completed='input-preflight' in completed,
        actual_final_readback=boolean((state.get('nss_configuration_final') or {}).get('configured')),
        unchanged_original_nss_guard=True,raw_account_or_nss_text_public=False),
      'CLEANUP.json':dict(schema='dg16.g1-intake-diagnostic-cleanup.v1',
        all_step_children_reaped=aggregate_child_observation(state),
        interrupted_step=enum_value(state.get('interrupted_step') or state.get('active_step'),STEPS,'NONE_OBSERVED'),
        prior_step_children_unknown=boolean(state.get('prior_step_children_unknown')) or state.get('active_step') is not None,
        last_cleanup=cleanup_projection(state.get('last_child_cleanup')),final_cleanup=cleanup_projection(state.get('final_child_cleanup')),
        policy_attempted=boolean(state.get('policy_attempted')),policy_finalized=boolean(state.get('policy_finalized')),
        policy_finalization_sha256=hash_value(state.get('policy_finalization_sha256')),
        policy_disposition='OWNED_POLICY_RETAINED_UNTIL_VM_DISPOSAL_NO_UNLOAD_OR_UNLINK',
        source_unchanged=boolean(state.get('source_unchanged')),runtime_unchanged=boolean(state.get('runtime_unchanged')),
        private_outputs_uploaded=False,private_retention='LIVE_JOB_ONLY',exported_hashes_convey_currentness=False),
      'FAILURE.json':dict(schema='dg16.g1-intake-diagnostic-failure.v1',
        orchestration_failed=boolean(state.get('failed')),test_failed=observed_boolean(state.get('case_test_failed')),failures=failures)}
    need(set(docs)==set(PUBLIC_NAMES)-{'ARTIFACT_MANIFEST.json'},'PUBLIC_POPULATION')
    return docs


def public_files(state):
    files={name:canonical(value) for name,value in public_projection(state).items()}
    files['ARTIFACT_MANIFEST.json']=canonical(dict(schema='dg16.g1-intake-diagnostic-artifacts.v1',members=[
        dict(name=name,bytes=len(raw),sha256=digest(raw)) for name,raw in sorted(files.items())]))
    validate_transport(files)
    return files


def validate_transport(files):
    need(set(files)==set(PUBLIC_NAMES),'PUBLIC_FILE_ALLOWLIST')
    total=0;encoded=0;lines=[]
    for name in PUBLIC_NAMES:
        raw=files[name];need(type(raw) is bytes and len(raw)<=PUBLIC_FILE_BYTES,'PUBLIC_FILE_BOUND')
        need(canonical(parse_json(raw))==raw,'PUBLIC_CANONICAL_JSON')
        total+=len(raw)
        line='DG16_G1_INTAKE_EVIDENCE '+name+' '+base64.b64encode(raw).decode('ascii')
        encoded+=len(line)+1;need(len(line)+1<=ENCODED_LINE_BYTES,'PUBLIC_LINE_BOUND');lines.append(line)
    need(total<=163840 and encoded<=655360,'PUBLIC_AGGREGATE_BOUND')
    expected=dict(schema='dg16.g1-intake-diagnostic-artifacts.v1',members=[
        dict(name=name,bytes=len(raw),sha256=digest(raw)) for name,raw in sorted(files.items()) if name!='ARTIFACT_MANIFEST.json'])
    need(parse_json(files['ARTIFACT_MANIFEST.json'])==expected,'PUBLIC_MANIFEST_BINDING')
    return lines


def write_public(state,output):
    files=public_files(state)
    need(not any((output/'public').iterdir()),'PUBLIC_OUTPUT_ALREADY_EXISTS')
    for name,raw in files.items():
        path=output/'public'/name;write_private(path,raw);os.chmod(path,0o644)
    for name,raw in files.items():need(read_regular(output/'public'/name,PUBLIC_FILE_BYTES)==raw,'PUBLIC_READBACK')


def emit_public(output):
    held=read_regular(output/'private/episode.json',4*1024**2);state=parse_json(held)
    expected=public_files(state)
    need({p.name for p in (output/'public').iterdir()}==set(PUBLIC_NAMES),'PUBLIC_DIRECTORY_POPULATION')
    actual={name:read_regular(output/'public'/name,PUBLIC_FILE_BYTES) for name in PUBLIC_NAMES}
    need(actual==expected,'PUBLIC_PRIVATE_PROJECTION_MISMATCH')
    lines=validate_transport(actual)
    need(effect_observations(output)==state['effect_observations'],'PUBLIC_EFFECT_CLOSING_CHANGED')
    need(read_regular(output/'private/episode.json',4*1024**2)==held,'PUBLIC_STATE_CLOSING_CHANGED')
    for line in lines:print(line,flush=True)
    marker=output/'PUBLIC_ELIGIBLE';write_private(marker,b'true\n');os.chmod(marker,0o644)


def emit_failure_observation(output,context):
    if (output/'PUBLIC_ELIGIBLE').exists():return
    need(not (output/'FAILURE_ELIGIBLE').exists(),'FALLBACK_ALREADY_EMITTED')
    records={}
    for role,name,limit in (('STATE','episode.json',4*1024**2),
        ('ADMISSION_STDOUT','source-admission.stdout',1024*1024),('ADMISSION_STDERR','source-admission.stderr',1024*1024),
        ('MATRIX_RESULT','access-matrix/result.json',65536),
        ('MATRIX_RESULT_ABSENCE','access-matrix/not-an-authority',1),('NSS','NSS_CONFIGURATION.json',8192),
        ('PARENT_CHECKPOINT','G3_EFFECT_STATE.json',4096)):
        row=dict(status='NOT_OBSERVED',bytes=None,sha256=None)
        try:
            raw=read_regular(output/'private'/name,limit)
            row=dict(status='EXACT_BOUNDED_BYTES',bytes=len(raw),sha256=digest(raw))
        except FileNotFoundError:pass
        except Exception:row['status']='UNREADABLE_OR_GUARD_REFUSED'
        records[role]=row
    value=dict(schema='dg16.g1-intake-diagnostic-retention-failure.v1',authority='NONE',
        reason='PRIMARY_VALIDATED_PUBLIC_EXPORT_UNAVAILABLE',**context,source_commit=SOURCE_COMMIT,source_tree=SOURCE_TREE,
        records=records,effects=effect_observations(output),unknown_means_no_effect=False,
        bank_acceptance=False,original_G1_award=False,original_G3_award=False,raw_private_outputs_uploaded=False)
    validate_effect_observations(value['effects']);raw=canonical(value);need(len(raw)<=24576,'FALLBACK_BOUND')
    files={'RETENTION_FAILURE.json':raw}
    files['ARTIFACT_MANIFEST.json']=canonical(dict(schema='dg16.g1-intake-diagnostic-fallback-artifacts.v1',members=[
        dict(name='RETENTION_FAILURE.json',bytes=len(raw),sha256=digest(raw))]))
    need(sum(map(len,files.values()))<=32768,'FALLBACK_TOTAL_BOUND')
    folder=output/'public-failure';folder.mkdir(mode=0o755)
    for name,data in files.items():
        write_private(folder/name,data);os.chmod(folder/name,0o644)
    for name,data in files.items():need(read_regular(folder/name,24576)==data,'FALLBACK_READBACK')
    # Main <=163840 plus fallback <=32768 remains below the unchanged262144.
    need(sum(map(len,files.values()))+163840<=PUBLIC_TOTAL_BYTES,'CUMULATIVE_PUBLIC_BOUND')
    for name,data in files.items():
        line='DG16_G1_INTAKE_FALLBACK '+name+' '+base64.b64encode(data).decode('ascii')
        need(len(line)+1<=ENCODED_LINE_BYTES,'FALLBACK_ENCODED_BOUND')
        print(line,flush=True)
    marker=output/'FAILURE_ELIGIBLE';write_private(marker,b'true\n');os.chmod(marker,0o644)


def main():
    os.umask(0o022)
    parser=argparse.ArgumentParser();parser.add_argument('--step',choices=(*STEPS,'finalize'))
    parser.add_argument('--emit-public',action='store_true');parser.add_argument('--emit-failure',action='store_true')
    parser.add_argument('--source',required=True);parser.add_argument('--output',required=True)
    args=parser.parse_args();need(sum(map(bool,(args.step,args.emit_public,args.emit_failure)))==1,'MODE_REFUSED')
    source=Path(args.source).absolute();output=Path(args.output).absolute()
    if args.emit_public:
        host_context(output,source);require_complete_packet();emit_public(output);return 0
    if args.emit_failure:
        context=host_context(output,source);require_complete_packet();emit_failure_observation(output,context);return 0
    return execute(args.step,source,output)


if __name__=='__main__':
    raise SystemExit(main())
